            <ol v-if="section.entries.length"><li v-for="story in section.entries.slice(0,4)" :key="story.id"><a :href="story.item.url" target="_blank" rel="noopener noreferrer" :title="story.item.originalTitle">{{story.item.title}}</a><span>{{story.item.sourceLabel}}</span></li></ol>
