<script setup>
import {computed,ref,onMounted,onUnmounted} from 'vue';
import {aiEditorialLayout,aiEditorialHistogram} from '@/utils/aiEditorialLayout.mjs';
import DisclosureChevron from '@/components/ui/DisclosureChevron.vue';
const props=defineProps({lanes:{type:Array,default:()=>[]},feeds:{type:Array,default:()=>[]},locale:{type:String,default:'zh-CN'},updatedAt:{type:[String,Number],default:null},sourceCount:{type:Number,default:0},healthyCount:{type:Number,default:0},totalCount:{type:Number,default:0},loading:Boolean});
const emit=defineEmits(['close','select']),zh=computed(()=>props.locale.startsWith('zh'));
const wallRoot=ref(null),selected=ref('all'),hours=ref(72),now=ref(Date.now());
const windows=[{hours:24,zh:'近1天',en:'1 day'},{hours:72,zh:'近3天',en:'3 days'},{hours:168,zh:'近7天',en:'7 days'}];
const edition=computed(()=>aiEditorialLayout(props.lanes,{hours:hours.value,selected:selected.value,now:now.value}));
const histogram=computed(()=>aiEditorialHistogram(props.lanes,{now:now.value}));
const latestTime=computed(()=>{const ms=Date.parse(String(props.updatedAt||''));return Number.isFinite(ms)?new Date(ms).toISOString():null;});
const dateText=value=>{const date=new Date(value);return Number.isFinite(date.getTime())?new Intl.DateTimeFormat(props.locale,{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(date):'—';};
const barHeight=count=>Math.max(count>0?8:0,Math.round(count/Math.max(1,...histogram.value.map(x=>x.count))*100));
const statusStats=computed(()=>[{kind:'ok',label:zh.value?'正常':'Healthy',count:props.feeds.filter(f=>f.status==='ok'&&!f.stale).length},{kind:'warning',label:zh.value?'失败或过期':'Failed / stale',count:props.feeds.filter(f=>['failed','error','stale'].includes(f.status)||f.stale).length},{kind:'unknown',label:zh.value?'未知或空':'Unknown / empty',count:props.feeds.filter(f=>!['ok','failed','error','stale'].includes(f.status)&&!f.stale).length}]);
let previousOverflow,previousFocus,previousAppInert,appRoot;
const handleDialogKey=event=>{if(event.key==='Escape'){event.preventDefault();emit('close');return;}if(event.key!=='Tab')return;const nodes=[...(wallRoot.value?.querySelectorAll('a[href],button:not([disabled]),select,[tabindex]:not([tabindex="-1"])')||[])];if(!nodes.length){event.preventDefault();wallRoot.value?.focus();return;}if(event.shiftKey&&document.activeElement===nodes[0]){event.preventDefault();nodes.at(-1).focus();}else if(!event.shiftKey&&document.activeElement===nodes.at(-1)){event.preventDefault();nodes[0].focus();}};
onMounted(()=>{previousOverflow=document.body.style.overflow;previousFocus=document.activeElement;
  appRoot=document.getElementById('app');previousAppInert=appRoot?.inert ?? false;
  document.body.style.overflow='hidden';
  // Teleport lives outside #app: native inert hides only the background from
  // keyboard and assistive tech, while the command-room dialog remains active.
  if(appRoot)appRoot.inert=true;
  wallRoot.value?.querySelector('.close-wall')?.focus({preventScroll:true});
});
onUnmounted(()=>{if(appRoot)appRoot.inert=previousAppInert;document.body.style.overflow=previousOverflow||'';
  previousFocus?.focus?.({preventScroll:true});
});
</script>
